Method.Implementation:
   Set tSC=$$$OK
   //Set pInput=$classmethod(..#CONTAINERCLASS,"%New",pInput)
   Set tSC=..resolveAndIndex(pInput) Quit:$$$ISERR(tSC) tSC
   Set pOutput = $$$NULLOREF
   $$$SyncCommitSet(tSyncCommit)
   //$$$TRACE("Rick - DebugA RecordMapIn is: " _RecordMapIn)
   $$$TRACE("Rick - Debug In OnProcessInput")
   //Create a stream object of type %IO.MetaCharacterStream
   set tIOStream=##class(%IO.MetaCharacterStream).%New(pInput)
   $$$TRACE("Rick - Debug2 tIOStream is: " _tIOStream.Read())
   //Loop through the input stream to create one RecordMap object for each line of record
   do tIOStream.Rewind()
   $$$TRACE("Rick - Debug2a In OnProcessInput ..recordMapFull is: " _..recordMapFull)
   While 'tIOStream.AtEnd
   {
     //Create the Record Map object from the stream
     Set tStatus = $classmethod(..recordMapFull, "GetObject", tIOStream, .tObject, -1, "", 0)
     $$$TRACE("Rick - Debug3 In OnProcessInput tStatus is: " _tStatus)
     //If $$$ISERR(tStatus) || (tPosition=tIOStream.Position) //Quit
     $$$TRACE("Rick - Debug4 ProgramName is:" _$IsObject(tObject))
     //Set tSC1=..SendRequestAsync(tOneTarget,tObject) Set:$$$ISERR(tSC1) tSC=$$$ADDSC(tSC,tSC1)
   }

   For iTarget=1:1:$L(..TargetConfigNames, ",") { Set tOneTarget=$ZStrip($P(..TargetConfigNames,",",iTarget),"<>W") Continue:""=tOneTarget
      $$$TRACE("Rick - Debug5 In OnProcessInput Entered For loop")
      If '..SyncCall 
      {
         $$$TRACE("Rick - Debug6")
         $$$sysTRACE("Sending input Stream "_pInput_" Async to '"_tOneTarget)

         //add your $classmethod() here and change the pInput to tObject at the next line 
         //Create the Record Map object from the stream
         //Set tStatus = $classmethod(..RecordMapIn, "GetObject", pInput, .tObject)

         Set tSC1=..SendRequestAsync(tOneTarget,tObject) Set:$$$ISERR(tSC1) tSC=$$$ADDSC(tSC,tSC1)
         } 
         Else 
         {
	        $$$TRACE("Rick - Debug7")
            $$$sysTRACE("Sending input Stream "_pInput_" Sync to '"_tOneTarget)
            //add your $classmethod() here and change the pInput to tObject at the next line
            //Create the Record Map object from the stream
            //Set tStatus = $classmethod(..RecordMapIn, "GetObject", pInput, .tObject)

            Set tSC1=..SendRequestSync(tOneTarget,tObject,.pOutput,..SyncCallTimeout) Set:$$$ISERR(tSC1) tSC=$$$ADDSC(tSC,tSC1)
         }
      }
      $$$SyncCommitClear(tSyncCommit)
      If ..SendAcknowledgement 
      {
	     $$$TRACE("Rick - Debug8")
         If ..SyncCall 
         {
	        $$$TRACE("Rick - Debug9")
            If (($G(pOutput)="")||($IsObject($G(pOutput)&&('pOutput.%IsA("%Stream.Object")&&'pOutput.%IsA("Ens.StreamContainer")&&'pOutput.%IsA("Ens.StringContainer")&&'pOutput.%IsA("Ens.StringRequest")&&'pOutput.%IsA("Ens.StringResponse"))))) 
            {
	           $$$TRACE("Rick - Debug10")
               Set pOutput=##Class(%IO.StringStream).%New(..AckNotOKAsChars)
            }
         } 
         Else 
         {
	        $$$TRACE("Rick - Debug11")
            Set pOutput=##Class(%IO.StringStream).%New($S($$$ISOK(tSC):..AckOKAsChars,1:..AckNotOKAsChars))
         }
      }
   $$$TRACE("Rick - Debug12")
   Quit tSC

    $$$TRACE("Rick - Debug In OnInit")
    //$$$sysTRACE("Rick - Debug In OnInit")
    Try 
    {
       #; No need to convert if not sending back an acknowledgement
       //Quit:'..SendAcknowledgement
       #; Convert ACK/NACK settings to characters
       //Set ..AckOKAsChars = ..Adapter.AsciiOrHexAsChars(..AckOK)
       //Set ..AckNotOKAsChars = ..Adapter.AsciiOrHexAsChars(..AckNotOK)

       //Add your OnInit code here
       //If $$$ISERR(tStatus) Quit tStatus

	   If '##class(EnsLib.RecordMap.RecordMap).Exists(..RecordMapIn) 
	   {
		   $$$TRACE("Rick - Debug2 In OnInit")

		   Quit //$$$ERROR($$$ClassDoesNotExist, ..RecordMapIn)
	   }
	   else
	   {
		  $$$TRACE("Rick - Debug3 In OnInit")
	      Set ..recordMapFull = $$$NormalizeClassname(..RecordMapIn)
	      $$$TRACE("Rick - Debug In OnInit recordMapFull is: " _..recordMapFull)



	   }
	   Set tTargetClass = $$$comMemberKeyGet(..recordMapFull,$$$cCLASSparameter,"OBJECTNAME",$$$cPARAMdefault)
	   If tTargetClass = "" Quit //$$$ERROR($$$EnsRecordMapErrNoDefaultObject,..recordMapFull)

	   If '##class(%Dictionary.CompiledClass).%ExistsId(tTargetClass) Quit //$$$ERROR($$$ClassDoesNotExist, tTargetClass)
	   If '$classmethod(tTargetClass, "%Extends", "EnsLib.RecordMap.Base") Quit //$$$ERROR($$$EnsRecordMapErrInvalidClass, tTargetClass, "EnsLib.RecordMap.Base")


	   //Quit tStatus

    } 
    Catch {}
    Quit ##super()
